import json, os
d = json.load(open(os.path.join(os.environ["LOCALAPPDATA"], "hermes", "trello-sync", "raw_cards.json"), encoding="utf-8"))

SKIP = ("Finalizado", "Finalizados", "Segunda", "Terça", "Quarta", "Quinta", "Sexta", "Sábado")
for board, b in d.items():
    print(f"\n===== {board} =====")
    for lst in b["lists"]:
        if any(lst["name"].startswith(s) for s in SKIP):
            continue
        open_cards = [c for c in lst["cards"] if not c["closed"]]
        print(f"\n-- {lst['name']} ({len(open_cards)})")
        for c in open_cards:
            due = (c.get("due") or {}).get("date")
            labels = ",".join(l["name"] for l in c.get("labels", []) if l.get("name"))
            members = ",".join(m.get("fullName","") for m in c.get("members", []))
            cls = c.get("checklists") or []
            chk = sum(len(x.get("checkItems",[])) for x in cls)
            chkd = sum(1 for x in cls for i in x.get("checkItems",[]) if i.get("state")=="complete")
            extra = []
            if due: extra.append(f"due={due[:10]}")
            if labels: extra.append(f"labels={labels}")
            if members: extra.append(f"resp={members}")
            if chk: extra.append(f"check={chkd}/{chk}")
            if c.get("description","").strip(): extra.append(f"desc={len(c['description'])}ch")
            print(f"   * {c['name']}  [{c['shortUrl']}] {' '.join(extra)}")
"}

